// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        // Restrict caller to be the current CEO (the initial ceoAddress)
        vm.assume(caller == c.ceoAddress());
        // Call DrugDealer() as the CEO
        vm.prank(caller);
        c.DrugDealer();
        // After call, ceoAddress must equal the caller's address
        assertTrue(c.ceoAddress() == caller);
    }
}

